module tb;
    reg [7:0] in;
    wire [31:0] out;

    TopModule dut (
        .in(in),
        .out(out)
    );

    initial begin
        // Test positive number
        in = 8'h05; // 4'b0101 equivalent or just 8'h05 (5)
        #1;
        if (out !== 32'h00000005) begin
            $display("SELFTEST FAIL: in=%h, expected=32'h00000005, got=%h", in, out);
            $finish;
        end

        // Test negative number
        in = 8'hFD; // -3
        #1;
        if (out !== 32'hFFFFFFFD) begin
            $display("SELFTEST FAIL: in=%h, expected=32'hFFFFFFFD, got=%h", in, out);
            $finish;
        end

        // Test zero
        in = 8'h00;
        #1;
        if (out !== 32'h00000000) begin
            $display("SELFTEST FAIL: in=%h, expected=32'h00000000, got=%h", in, out);
            $finish;
        end

        // Test max negative (-1)
        in = 8'hFF;
        #1;
        if (out !== 32'hFFFFFFFF) begin
            $display("SELFTEST FAIL: in=%h, expected=32'hFFFFFFFF, got=%h", in, out);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
